content:
Below is an idiomatic Pulumi TypeScript `ComponentResource` that wraps:

- an **S3 bucket** with versioning, encryption, and public access blocked
- an **RDS PostgreSQL instance** with deletion protection, backup retention, and private-only access
- an **IAM role for service accounts** using **OIDC trust** (good fit for EKS service accounts)

It also supports **dev/prod via stack config**.

---

## Suggested project structure

```txt
pulumi/
├─ index.ts
├─ infra/
│  └─ appInfra.ts
├─ Pulumi.yaml
├─ Pulumi.dev.yaml
└─ Pulumi.prod.yaml
```

---

# `infra/appInfra.ts`

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface AppInfraArgs {
    vpcId: pulumi.Input<string>;
    privateSubnetIds: pulumi.Input<pulumi.Input<string>[]>;
    dbSecurityGroupId: pulumi.Input<string>;

    /**
     * EKS OIDC provider ARN, used for IAM role trust policy.
     * Example: arn:aws:iam::<acct>:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/XXXX
     */
    oidcProviderArn: pulumi.Input<string>;

    /**
     * EKS OIDC issuer URL, without https:// in IAM condition key logic we strip it.
     * Example: https://oidc.eks.us-east-1.amazonaws.com/id/XXXX
     */
    oidcProviderUrl: pulumi.Input<string>;

    /**
     * Kubernetes service account identity allowed to assume the role.
     */
    k8sNamespace: pulumi.Input<string>;
    k8sServiceAccountName: pulumi.Input<string>;

    /**
     * Optional DB admin username.
     */
    dbUsername?: pulumi.Input<string>;

    /**
     * DB password should come from Pulumi config secret.
     */
    dbPassword: pulumi.Input<string>;

    /**
     * Optional DB name.
     */
    dbName?: pulumi.Input<string>;

    /**
     * Optional tags.
     */
    tags?: Record<string, pulumi.Input<string>>;
}

export interface AppInfraOutputs {
    bucketName: pulumi.Output<string>;
    bucketArn: pulumi.Output<string>;
    dbEndpoint: pulumi.Output<string>;
    dbPort: pulumi.Output<number>;
    dbName: pulumi.Output<string>;
    iamRoleArn: pulumi.Output<string>;
    dbConnectionString: pulumi.Output<string>;
}

export class AppInfra extends pulumi.ComponentResource implements AppInfraOutputs {
    public readonly bucketName: pulumi.Output<string>;
    public readonly bucketArn: pulumi.Output<string>;
    public readonly dbEndpoint: pulumi.Output<string>;
    public readonly dbPort: pulumi.Output<number>;
    public readonly dbName: pulumi.Output<string>;
    public readonly iamRoleArn: pulumi.Output<string>;
    public readonly dbConnectionString: pulumi.Output<string>;

    constructor(name: string, args: AppInfraArgs, opts?: pulumi.ComponentResourceOptions) {
        super("custom:infra:AppInfra", name, {}, opts);

        const stack = pulumi.getStack();
        const isProd = stack === "prod";

        const tags = {
            "pulumi:component": name,
            "environment": stack,
            ...args.tags,
        };

        //
        // S3 bucket
        //
        const bucket = new aws.s3.BucketV2(`${name}-assets`, {
            tags,
        }, { parent: this });

        new aws.s3.BucketVersioningV2(`${name}-assets-versioning`, {
            bucket: bucket.id,
            versioningConfiguration: {
                status: "Enabled",
            },
        }, { parent: this });

        new aws.s3.BucketServerSideEncryptionConfigurationV2(`${name}-assets-sse`, {
            bucket: bucket.id,
            rules: [
                {
                    applyServerSideEncryptionByDefault: {
                        sseAlgorithm: "AES256",
                    },
                },
            ],
        }, { parent: this });

        new aws.s3.BucketPublicAccessBlock(`${name}-assets-pab`, {
            bucket: bucket.id,
            blockPublicAcls: true,
            blockPublicPolicy: true,
            ignorePublicAcls: true,
            restrictPublicBuckets: true,
        }, { parent: this });

        // Optional: prod cross-region replication could be added here if desired.
        // Not included because replication requires destination bucket + replication role setup.

        //
        // IAM role for service account (IRSA / OIDC)
        //
        const oidcHostPath = pulumi.output(args.oidcProviderUrl).apply(url =>
            url.replace("https://", "")
        );

        const assumeRolePolicy = pulumi.all([
            args.oidcProviderArn,
            oidcHostPath,
            args.k8sNamespace,
            args.k8sServiceAccountName,
        ]).apply(([providerArn, hostPath, namespace, saName]) =>
            JSON.stringify({
                Version: "2012-10-17",
                Statement: [
                    {
                        Effect: "Allow",
                        Principal: {
                            Federated: providerArn,
                        },
                        Action: "sts:AssumeRoleWithWebIdentity",
                        Condition: {
                            StringEquals: {
                                [`${hostPath}:sub`]: `system:serviceaccount:${namespace}:${saName}`,
                                [`${hostPath}:aud`]: "sts.amazonaws.com",
                            },
                        },
                    },
                ],
            })
        );

        const role = new aws.iam.Role(`${name}-sa-role`, {
            assumeRolePolicy,
            tags,
        }, { parent: this });

        const bucketPolicyDoc = pulumi.all([bucket.arn]).apply(([bucketArn]) =>
            JSON.stringify({
                Version: "2012-10-17",
                Statement: [
                    {
                        Sid: "ListBucket",
                        Effect: "Allow",
                        Action: ["s3:ListBucket"],
                        Resource: bucketArn,
                    },
                    {
                        Sid: "BucketObjectsAccess",
                        Effect: "Allow",
                        Action: isProd
                            ? ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
                            : ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"],
                        Resource: `${bucketArn}/*`,
                    },
                ],
            })
        );

        new aws.iam.RolePolicy(`${name}-sa-bucket-policy`, {
            role: role.id,
            policy: bucketPolicyDoc,
        }, { parent: this });

        //
        // RDS PostgreSQL
        //
        const subnetGroup = new aws.rds.SubnetGroup(`${name}-db-subnets`, {
            subnetIds: args.privateSubnetIds,
            tags,
        }, { parent: this });

        const dbName = pulumi.output(args.dbName ?? "appdb");
        const dbUsername = pulumi.output(args.dbUsername ?? "appuser");

        const dbInstance = new aws.rds.Instance(`${name}-db`, {
            engine: "postgres",
            engineVersion: "16.3",
            instanceClass: isProd ? "db.t3.medium" : "db.t3.micro",
            allocatedStorage: isProd ? 100 : 20,
            maxAllocatedStorage: isProd ? 500 : 100,

            dbSubnetGroupName: subnetGroup.name,
            vpcSecurityGroupIds: [args.dbSecurityGroupId],

            dbName: dbName,
            username: dbUsername,
            password: args.dbPassword,

            storageEncrypted: true,
            deletionProtection: true,
            backupRetentionPeriod: 7,
            publiclyAccessible: false,
            multiAz: isProd,

            skipFinalSnapshot: false,
            finalSnapshotIdentifier: `${name}-${stack}-final-snapshot`,

            autoMinorVersionUpgrade: true,
            applyImmediately: false,

            tags,
        }, {
            parent: this,
            protect: isProd,
        });

        const connectionString = pulumi.secret(
            pulumi.interpolate`postgresql://${dbUsername}:${args.dbPassword}@${dbInstance.address}:${dbInstance.port}/${dbName}`
        );

        this.bucketName = bucket.bucket;
        this.bucketArn = bucket.arn;
        this.dbEndpoint = dbInstance.address;
        this.dbPort = dbInstance.port;
        this.dbName = dbName;
        this.iamRoleArn = role.arn;
        this.dbConnectionString = connectionString;

        this.registerOutputs({
            bucketName: this.bucketName,
            bucketArn: this.bucketArn,
            dbEndpoint: this.dbEndpoint,
            dbPort: this.dbPort,
            dbName: this.dbName,
            iamRoleArn: this.iamRoleArn,
            dbConnectionString: this.dbConnectionString,
        });
    }
}
```

