# `index.ts`

This shows how to consume the component using **stack config** for `dev` and `prod`.

```ts
import * as pulumi from "@pulumi/pulumi";
import { AppInfra } from "./infra/appInfra";

const config = new pulumi.Config();

const vpcId = config.require("vpcId");
const privateSubnetIds = config.requireObject<string[]>("privateSubnetIds");
const dbSecurityGroupId = config.require("dbSecurityGroupId");

const oidcProviderArn = config.require("oidcProviderArn");
const oidcProviderUrl = config.require("oidcProviderUrl");

const k8sNamespace = config.get("k8sNamespace") || "default";
const k8sServiceAccountName = config.get("k8sServiceAccountName") || "app-sa";

const dbUsername = config.get("dbUsername") || "appuser";
const dbPassword = config.requireSecret("dbPassword");
const dbName = config.get("dbName") || "appdb";

const app = new AppInfra("app", {
    vpcId,
    privateSubnetIds,
    dbSecurityGroupId,
    oidcProviderArn,
    oidcProviderUrl,
    k8sNamespace,
    k8sServiceAccountName,
    dbUsername,
    dbPassword,
    dbName,
    tags: {
        project: "canonical-app",
    },
});

export const bucketName = app.bucketName;
export const dbEndpoint = app.dbEndpoint;
export const iamRoleArn = app.iamRoleArn;
export const dbConnectionString = app.dbConnectionString;
```

